import std.io

pub type AppError = Failed(String)

newtype UserId(Int64)
newtype Name(String)

fn raw(id: UserId) -> Int64 {
    return id.value
}

fn label(n: Name) -> String {
    return n.value
}

pub fn main() effect io -> Result<(), AppError> {
    let id = UserId(41)
    let alias = id
    io.println("${raw(alias) + 1} ${label(Name("id"))} ${id.value}")
    return Ok(())
}
